using Ecom.Domain.Entities;

namespace Ecom.Application.Features.Commerce.Producers.Commands.CreateProductionFacility;
public sealed record CreateProductionFacilityCommand(Guid ProducerId,Guid ProducerConcurrencyStamp,Guid? AdministrativeAreaId,string Name,string? AddressLine,decimal? Latitude,decimal? Longitude,string? Description):IRequest<TResult<ProductionFacilityDto>>,ITransactionalRequest;
public sealed class CreateProductionFacilityCommandValidator:AbstractValidator<CreateProductionFacilityCommand>{public CreateProductionFacilityCommandValidator(){RuleFor(x=>x.ProducerId).NotEmpty();RuleFor(x=>x.ProducerConcurrencyStamp).NotEmpty();RuleFor(x=>x.Name).NotEmpty().MaximumLength(256);RuleFor(x=>x.AddressLine).MaximumLength(1000);RuleFor(x=>x.Description).MaximumLength(4000);RuleFor(x=>x.Latitude).InclusiveBetween(-90,90).When(x=>x.Latitude.HasValue);RuleFor(x=>x.Longitude).InclusiveBetween(-180,180).When(x=>x.Longitude.HasValue);}}
public sealed class CreateProductionFacilityCommandHandler(IUnitOfWork uow,ProducerManagementService service):IRequestHandler<CreateProductionFacilityCommand,TResult<ProductionFacilityDto>>
{public async Task<TResult<ProductionFacilityDto>> Handle(CreateProductionFacilityCommand r,CancellationToken ct){var loaded=await service.LoadAsync(r.ProducerId,r.ProducerConcurrencyStamp,Permissions.Producers.Update,ct);if(!loaded.IsSuccess)return TResult<ProductionFacilityDto>.Failure(loaded.Error!,loaded.ErrorCode);if(r.AdministrativeAreaId.HasValue&&!await uow.Repository<AdministrativeArea>().AnyAsync([x=>x.Id==r.AdministrativeAreaId]))return TResult<ProductionFacilityDto>.Failure(MessageKey.ResourceNotFound,ErrorCodes.NOT_FOUND);var facility=ProductionFacility.Create(loaded.Data.Id,r.AdministrativeAreaId,r.Name,r.AddressLine,r.Latitude,r.Longitude,r.Description);loaded.Data.RenewConcurrencyStamp();await uow.Repository<ProductionFacility>().InsertAsync(facility,ct);await uow.Repository<Producer>().UpdateAsync(loaded.Data,ct);return TResult<ProductionFacilityDto>.Success(ProducerManagementService.Map(facility));}}
